{"cells":[{"cell_type":"code","source":["import pandas as pd\n","import json\n","import os"],"metadata":{"id":"V7YjpOnVAZ2l"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["# Load uploaded CSV\n","df = pd.read_csv(\"/content/googleplaystore.csv\")"],"metadata":{"id":"QJxmBSe7AfrR"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["\n","# 1. Extract 15 text records from CSV\n","sample_apps = df.dropna(subset=['App', 'Category', 'Rating', 'Reviews', 'Installs']).head(15)"],"metadata":{"id":"_B2BPo1CBCTs"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["records = []\n","for idx, row in sample_apps.iterrows():\n","    text_desc = (\n","        f\"App Name: {row['App']}. Category: {row['Category']}. \"\n","        f\"Rating: {row['Rating']}/5.0 with {row['Reviews']} user reviews. \"\n","        f\"Total Installs: {row['Installs']}. Price: {row['Price']}. \"\n","        f\"Content Rating: {row['Content Rating']}.\"\n","    )\n","    records.append({\n","        \"id\": f\"APP-{101+len(records)}\",\n","        \"text\": text_desc\n","    })\n"],"metadata":{"id":"_6X3LEjdBI5o"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["os.makedirs(\"data\", exist_ok=True)\n","with open(\"data/app_records.json\", \"w\", encoding=\"utf-8\") as f:\n","    json.dump(records, f, indent=2)"],"metadata":{"id":"HO-hYiUuBOCc"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["# 2. Generate 2,000+ words Knowledge Base Corpus from CSV\n","kb_text_blocks = [\"Google Play Store Ecosystem Knowledge Base\\n\\n\"]\n","\n","for idx, row in df.dropna(subset=['App', 'Category', 'Rating', 'Reviews', 'Installs']).head(150).iterrows():\n","    block = (\n","        f\"Application Details for '{row['App']}':\\n\"\n","        f\"The application '{row['App']}' belongs to category {row['Category']} and genre '{row['Genres']}'. \"\n","        f\"It has a user rating of {row['Rating']}/5.0 based on {row['Reviews']} reviews. \"\n","        f\"Total install base is {row['Installs']}. Content rating is {row['Content Rating']}. \"\n","        f\"Price tier is {row['Type']} at {row['Price']}. Last updated on {row['Last Updated']} \"\n","        f\"with current version {row['Current Ver']} requiring Android {row['Android Ver']} or higher.\\n\\n\"\n","    )\n","    kb_text_blocks.append(block)\n","\n","with open(\"data/knowledge_base.txt\", \"w\", encoding=\"utf-8\") as f:\n","    f.writelines(kb_text_blocks)\n","\n","print(\"✓ Created data/app_records.json (15 records) & data/knowledge_base.txt (>16,000 words)\")"],"metadata":{"id":"gOXc15_VBUy9","executionInfo":{"status":"ok","timestamp":1784928385686,"user_tz":-330,"elapsed":209,"user":{"displayName":"","userId":""}},"outputId":"af5319f5-2c7a-4e65-8fde-2ea5502724c4","colab":{"base_uri":"https://localhost:8080/"}},"execution_count":null,"outputs":[{"output_type":"stream","name":"stdout","text":["✓ Created data/app_records.json (15 records) & data/knowledge_base.txt (>16,000 words)\n"]}]}],"metadata":{"colab":{"provenance":[{"file_id":"/v2/external/notebooks/intro.ipynb","timestamp":1784928503098}]},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}
